import React, { useState, useEffect } from 'react';

const Dashboard = () => {
  const [offset, setOffset] = useState({ x: 0, y: 0 });

  const handleMouseMove = (e) => {
    const { innerWidth, innerHeight } = window;
    // حركة خفيفة للصورة بناءً على الماوس
    const x = (e.clientX / innerWidth - 0.5) * 20;
    const y = (e.clientY / innerHeight - 0.5) * 20;
    setOffset({ x, y });
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div className="container-fluid p-0 overflow-hidden" style={{ minHeight: '80vh' }}>
      <div className="row g-0 align-items-center" style={{ minHeight: '80vh' }}>
        
        {/* القسم النصي */}
        <div className="col-lg-6 p-5 fade-in">
          <div className="p-lg-5">
            <h1 className="display-3 fw-bold mb-4" style={{ background: 'linear-gradient(45deg, #667eea, #764ba2)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
              مستقبل العقارات <br/> بين يديك
            </h1>
            <p className="lead text-muted mb-5" style={{ lineHeight: '1.8' }}>
              منصة <strong>سمسار برو</strong> هي الحل الأمثل لإدارة وتسويق العقارات بذكاء. 
              نجمع بين التكنولوجيا الحديثة وسهولة الاستخدام لنوفر لك تجربة فريدة في البحث عن منزل أحلامك أو إدارة استثماراتك العقارية.
            </p>
            
            <div className="d-flex gap-3">
              <button 
                className="btn btn-primary btn-lg px-4 rounded-pill shadow-lg" 
                onClick={() => document.querySelector('[title="العقارات"]')?.click()}>
                تصفح العقارات
              </button>
              <button className="btn btn-outline-secondary btn-lg px-4 rounded-pill" onClick={() => document.querySelector('.contact-fab')?.click()} title="تواصل معنا">
                تواصل معنا
              </button>
              <button className="btn btn-success btn-lg px-4 rounded-pill shadow-lg" onClick={() => document.querySelector('#client-login-button')?.click()} title="سجل دخولك الآن">
                سجل دخولك الآن
              </button>
            </div>

            <div className="mt-5 pt-4 border-top">
              <div className="row text-center">
                <div className="col">
                  <h3 className="fw-bold text-primary">+500</h3>
                  <small className="text-muted">عقار متاح</small>
                </div>
                <div className="col">
                  <h3 className="fw-bold text-primary">+100</h3>
                  <small className="text-muted">عميل سعيد</small>
                </div>
                <div className="col">
                  <h3 className="fw-bold text-primary">24/7</h3>
                  <small className="text-muted">دعم فني</small>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* القسم التفاعلي 3D */}
        <div className="col-lg-6 d-flex justify-content-center align-items-center" style={{ height: '60vh', perspective: '1000px' }}>
          <div className="position-relative">
            <div className="position-absolute top-50 start-50 translate-middle bg-primary opacity-10 rounded-circle" style={{width: '400px', height: '400px', filter: 'blur(50px)', zIndex: 0}}></div>
            <img 
            src="https://images.unsplash.com/photo-1580587771525-78b9dba3b91d?ixlib=rb-1.2.1&auto=format&fit=crop&w=800&q=80" 
            alt="Modern Building" 
            className="img-fluid rounded-4 shadow-lg position-relative"
            style={{
                maxHeight: '500px',
                transform: `translate(${offset.x}px, ${offset.y}px)`,
                transition: 'transform 0.1s ease-out',
                zIndex: 1,
                border: '8px solid rgba(255,255,255,0.2)'
            }}
          />
          </div>
        </div>
      </div>

      <style>{`
      `}</style>
    </div>
  );
};

export default Dashboard;
